1	export type Direction = "N" | "E" | "S" | "W";
2	
3	export interface Rover {
4	  x: number;
5	  y: number;
6	  direction: Direction;
7	}
8	
9	const DIRECTION_AFTER_LEFT_TURN: Record<Direction, Direction> = {
10	  N: "W",
11	  W: "S",
12	  S: "E",
13	  E: "N",
14	};
15	
16	const DIRECTION_AFTER_RIGHT_TURN: Record<Direction, Direction> = {
17	  N: "E",
18	  E: "S",
19	  S: "W",
20	  W: "N",
21	};
22	
23	function facing(rover: Rover, direction: Direction): Rover {
24	  return { ...rover, direction };
25	}
26	
27	const STEP_FORWARD: Record<Direction, { dx: number; dy: number }> = {
28	  N: { dx: 0, dy: 1 },
29	  E: { dx: 1, dy: 0 },
30	  S: { dx: 0, dy: -1 },
31	  W: { dx: -1, dy: 0 },
32	};
33	
34	function movedForward(rover: Rover): Rover {
35	  const { dx, dy } = STEP_FORWARD[rover.direction];
36	  return { ...rover, x: rover.x + dx, y: rover.y + dy };
37	}
38	
39	const STEP_FOR_COMMAND: Record<string, (rover: Rover) => Rover> = {
40	  L: (rover) => facing(rover, DIRECTION_AFTER_LEFT_TURN[rover.direction]),
41	  R: (rover) => facing(rover, DIRECTION_AFTER_RIGHT_TURN[rover.direction]),
42	  F: movedForward,
43	};
44	
45	export function executeCommands(rover: Rover, commands: string): Rover {
46	  return [...commands].reduce(
47	    (current, command) => STEP_FOR_COMMAND[command](current),
48	    rover,
49	  );
50	}
